# Replace each character sequence with a hyphen.
#
# See Utils#slugify for a description of the character sequence specified
# by each mode.
def replace_character_sequence_with_hyphen(string, mode: "default")
  @slug_workspace ||= {}
  @slug_workspace[:replace_string] = string
  @slug_workspace[:replace_mode] = mode
  replaceable_char = slugify_replaceable_pattern(mode)
  string.gsub(replaceable_char, "-")
end
