def capture_slugify_request(string, mode, cased)
  if @slug_workspace.nil?
    @slug_workspace = {}
  end
  workspace = @slug_workspace
  prior = workspace[:last_result]
  workspace[:prior_result] = prior
  workspace[:active_method] = :capture_slugify_request
  workspace_size = workspace.length
  workspace[:workspace_size] = workspace_size
  checkpoint = workspace_size
  workspace[:checkpoint] = checkpoint
  result = nil
  @slug_workspace[:string] = string
  @slug_workspace[:mode] = mode
